import React, { useEffect, useState } from "react";
import { Container, Card, Button, Badge } from "react-bootstrap";

function Maps() {
  const [markers, setMarkers] = useState([]);
  const [selectedStop, setSelectedStop] = useState(null);

  useEffect(() => {
    fetch("http://localhost:3000/api/map-data")
      .then((res) => res.json())
      .then((data) => setMarkers(data))
      .catch((err) => console.error(err));
  }, []);

  // ค่าเริ่มต้นแผนที่ (กรุงเทพ)
  const lat = selectedStop ? selectedStop.latitude : 13.7563;
  const lng = selectedStop ? selectedStop.longitude : 100.5018;

  const mapSrc = `https://www.openstreetmap.org/export/embed.html?bbox=${lng -
    0.01},${lat - 0.01},${lng + 0.01},${lat +
    0.01}&layer=mapnik&marker=${lat},${lng}`;

  return (
    <Container fluid>
      <Card>
        <Card.Header>
          <Card.Title as="h4">🚌 Bus Stop Monitoring</Card.Title>
          <p className="card-category">
            ดูตำแหน่งป้ายและจำนวนคนรอรถ
          </p>
        </Card.Header>

        <Card.Body>
          {/* 🗺 MAP */}
          <div style={{ height: "400px", marginBottom: "20px" }}>
            <iframe
              title="map"
              width="100%"
              height="100%"
              frameBorder="0"
              src={mapSrc}
              style={{ borderRadius: "10px" }}
            />
          </div>

          {/* 📍 แสดงข้อมูลป้ายที่เลือก */}
          {selectedStop && (
            <Card
              style={{
                background: "#f8f9fa",
                marginBottom: "15px",
              }}
            >
              <Card.Body>
                <h5>📍 {selectedStop.Name}</h5>
                <p>
                  👥 จำนวนคนรอรถ:{" "}
                  <Badge bg="danger">
                    {selectedStop.people_count ?? 0} คน
                  </Badge>
                </p>
                <p style={{ fontSize: "13px", color: "#666" }}>
                  Lat: {selectedStop.latitude}, Lng:{" "}
                  {selectedStop.longitude}
                </p>
              </Card.Body>
            </Card>
          )}

          {/* 📋 LIST ป้ายรถ */}
          <h5>📌 รายการป้ายรถ</h5>
          {markers.map((stop, index) => (
            <Card
              key={index}
              style={{
                marginBottom: "10px",
                border:
                  selectedStop?.Name === stop.Name
                    ? "2px solid #dc3545"
                    : "1px solid #ddd",
              }}
            >
              <Card.Body
                style={{
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "center",
                }}
              >
                <div>
                  <strong>{stop.Name}</strong>
                  <br />
                  👥 คนรอรถ:{" "}
                  <Badge bg="secondary">
                    {stop.people_count ?? 0}
                  </Badge>
                </div>

                <Button
                  variant="primary"
                  size="sm"
                  onClick={() => setSelectedStop(stop)}
                >
                  ดูตำแหน่ง
                </Button>
              </Card.Body>
            </Card>
          ))}
        </Card.Body>
      </Card>
    </Container>
  );
}

export default Maps;
